// src/demos/meridian/receipts.test.ts
// The regression this file exists for: POST /decisions built its CaptureInput
// without `sections`, so every page-ordering receipt the client posted was
// dropped before it reached D1 — and the guard rejected a sections-only post
// outright. Page order is half the Experience milestone; its receipts were the
// half that never persisted.

import { describe, it, expect } from 'vitest';
import { capture, captureInputFrom, rowsForLayout, MRD_DECISION_COLUMNS } from './receipts';
import type { SectionDecision, SectionStrategy } from './types';

class FakeD1 {
  batched: unknown[][] = [];
  prepare(sql: string) {
    const self = this;
    return { bind: (...args: unknown[]) => ({ sql, args, _self: self }) } as never;
  }
  async batch(stmts: Array<{ args: unknown[] }>): Promise<unknown[]> {
    this.batched.push(...stmts.map((s) => s.args));
    return [];
  }
}

const section = (name: string, rank: number, strategy: SectionStrategy = 'affinity'): SectionDecision => ({
  section: name, rank, templateRank: rank, strategy, score: 0.42,
  explain: {
    drivers: [{ dim: 'line', value: 'drover', a: 0.7, weight: 1 }],
    lead: { shape: 'line', dim: 'line', value: 'drover' },
    confidence: 0.7, thetaOut: 0.45,
    movedBecause: `line-drover 0.70 >= thetaOut 0.45`,
    configVersion: 'v1',
  },
});
const decision = (slot: string, order: number) => ({
  slot, order, itemId: `item-${order}`, strategy: 'affinity',
  explain: { candidates: 12, drivers: [{ dim: 'line', value: 'drover', a: 0.7, weight: 1 }], configVersion: 'v1' },
  rankScore: 0.5,
} as never);

describe('captureInputFrom', () => {
  it('carries sections through — the field the route used to drop', () => {
    const input = captureInputFrom(
      { visitorId: 'v1', decisions: [decision('hero', 0)], sections: [section('offers', 1)] },
      'retail' as never, 1000,
    );
    expect(input).not.toBeNull();
    expect(input!.sections).toHaveLength(1);
    expect(input!.sections![0].section).toBe('offers');
  });

  it('accepts a sections-only post, which the old guard rejected with a 400', () => {
    const input = captureInputFrom({ visitorId: 'v1', sections: [section('offers', 1)] }, 'retail' as never, 1000);
    expect(input).not.toBeNull();
    expect(input!.decisions).toEqual([]);
    expect(input!.sections).toHaveLength(1);
  });

  it('accepts a decisions-only post, unchanged from before', () => {
    const input = captureInputFrom({ visitorId: 'v1', decisions: [decision('hero', 0)] }, 'retail' as never, 1000);
    expect(input!.decisions).toHaveLength(1);
    expect(input!.sections).toEqual([]);
  });

  it('is null when there is nothing to write, and when the visitor is missing', () => {
    expect(captureInputFrom({ visitorId: 'v1', decisions: [], sections: [] }, 'retail' as never, 1)).toBeNull();
    expect(captureInputFrom({ decisions: [decision('hero', 0)] }, 'retail' as never, 1)).toBeNull();
    expect(captureInputFrom({ visitorId: '  ' }, 'retail' as never, 1)).toBeNull();
    expect(captureInputFrom(null, 'retail' as never, 1)).toBeNull();
  });

  it('ignores non-array decisions/sections rather than throwing on bad input', () => {
    const input = captureInputFrom(
      { visitorId: 'v1', decisions: 'nope', sections: [section('offers', 1)] } as never, 'retail' as never, 1,
    );
    expect(input!.decisions).toEqual([]);
    expect(input!.sections).toHaveLength(1);
  });
});

describe('capture writes section rows', () => {
  it('persists one row per section, keyed as layout:<section>', async () => {
    const db = new FakeD1();
    const input = captureInputFrom(
      { visitorId: 'v1', sections: [section('offers', 1), section('editorial', 2)] }, 'retail' as never, 1000,
    )!;
    const n = await capture(db as never, input);
    expect(n).toBe(2);

    const slotIdx = MRD_DECISION_COLUMNS.indexOf('slot_id' as never);
    const slots = db.batched.map((row) => row[slotIdx]);
    expect(slots).toEqual(['layout:offers', 'layout:editorial']);
  });

  it('writes slot decisions and section decisions in ONE batch, so a page is one receipt', async () => {
    const db = new FakeD1();
    const input = captureInputFrom(
      { visitorId: 'v1', decisions: [decision('hero', 0), decision('rail', 1)], sections: [section('offers', 1)] },
      'retail' as never, 1000,
    )!;
    expect(await capture(db as never, input)).toBe(3);
    expect(db.batched).toHaveLength(3);
  });

  it('records a locked section with "locked" as the gate that outranked the engine', () => {
    const rows = rowsForLayout({
      visitorId: 'v1', vertical: 'retail' as never, now: 1,
      sections: [section('merch', 1, 'locked')],
    });
    const gatesIdx = MRD_DECISION_COLUMNS.indexOf('gates_failed' as never);
    expect(JSON.parse(rows[0][gatesIdx] as string)).toEqual(['locked']);
  });

  it('writes nothing rather than an empty batch when both lists are empty', async () => {
    const db = new FakeD1();
    expect(await capture(db as never, {
      visitorId: 'v1', vertical: 'retail' as never, decisions: [], sections: [], now: 1,
    })).toBe(0);
    expect(db.batched).toHaveLength(0);
  });
});

// src/identity/link.ts
// ---------------------------------------------------------------------------
// The link itself: a browser becomes a person's, and the profile follows.
//
// Whichever host holds the profile (the KV session today, the shopper object
// when REFLEX_HOST is 'do'), the steps are the same and in the same order:
//
//   1. name the person: shopperIdFor(tenant, accountId)
//   2. record the link, and learn whether this browser is new to the person,
//      already theirs, or moving from someone else
//   3. new: fold the browser's profile into the person's, and leave the
//      browser's record forwarding there
//      moving: only repoint; what it learned went to the first person
//      already: nothing
//   4. tell the client the id to carry from now on
//
// Step 3 is where the two hosts differ, and only there.
//
// WHAT A LINK IS NOT. It is not a login. The site knows who is signed in; this
// records that the site said so, with how much assurance, and merges profiles
// accordingly. And it is not reversible by design: a merged profile is one
// profile. "Log out" is a client act, detach (identity/detach) plus a fresh
// anonymous id, and the person's profile stays whole for their next sign-in.
// ---------------------------------------------------------------------------

import type { Env } from '@/types/env';
import type { TenantId } from '@/tenancy/tenant';
import { shopperObject, shopperObjectName } from '@/tenancy/objects';
import { resolveReflexConfig, resolveSurface } from '@/demos/registry';
import { SessionManager, type SessionData } from '@/services/SessionManager';
import type { ReflexChanges } from '@/reflex/core';
import { IdentityStore, type LinkSource } from '@/identity/store';
import { isSalted, isShopperId, shopperIdFor } from '@/identity/shopperId';
import type { Assurance } from '@/identity/assertion';
import { assertSessionTarget, SessionAccessError, SHOPPER_HEADER, type SessionCapability } from '@/identity/sessionCapability';
import { consentFromCookies, consentOf, intersectConsent, storedConsent, type Consent } from '@/content/consent';

export type LinkOutcome = 'linked' | 'already' | 'relinked';

export interface LinkResult {
  shopperId: string;
  visitorId: string;
  outcome: LinkOutcome;
  assurance: Assurance;
  /** Session host only: the person's session id, for the cookie. */
  sessionId: string | null;
  /** What the merge did to the person's memberships. Empty when nothing merged. */
  changes: ReflexChanges;
  audiences: string[];
  cookieHeaders: string[];
  consent?: Consent;
}

/** A visitor id we will link: the client's own format, bounded, never a namespace. */
export function validVisitorId(id: unknown): id is string {
  return typeof id === 'string' && /^[A-Za-z0-9_.\-]{1,200}$/.test(id);
}

export async function linkVisitor(
  env: Env,
  tenant: TenantId,
  input: {
    visitorId: string; accountId: string; source: LinkSource; assurance: Assurance; now?: number;
    /** The session id on the request's cookie, if any: where the browser's own record lives once its `user:` key points at a person. */
    cookieSessionId?: string | null;
    /** Public link ingress only; trusted history/import callers omit this. */
    principal?: SessionCapability;
    capability?: string;
    cookieHeader?: string | null;
  },
): Promise<LinkResult> {
  const now = input.now ?? Date.now();
  let ownedSource: { id: string; data: SessionData } | null | undefined;
  let sourceConsent: Consent | undefined;
  let ownedObjectSource: { affinity?: unknown; pipeline?: unknown; forwardTo?: unknown } | undefined;
  if (input.principal) {
    assertSessionTarget(input.principal, input.visitorId);
    if (input.principal.kind !== 'anonymous' || input.principal.tenant !== tenant) throw new SessionAccessError();
    if ((env.REFLEX_HOST ?? 'session') !== 'do') {
      const data = await new SessionManager(env, { tenant, principal: input.principal }).readRaw(input.principal.sessionId, true);
      ownedSource = data ? { id: input.principal.sessionId, data } : null;
      sourceConsent = consentOf(data);
    } else {
      const res = await shopperObject(env.SHOPPER_REFLEX, input.visitorId, tenant).fetch('https://shopper-reflex/identity/export', {
        headers: { [SHOPPER_HEADER]: input.capability ?? '', 'X-Tenant': tenant },
      });
      if (!res.ok) throw new SessionAccessError();
      const source = await res.json() as { forwardTo?: unknown; affinity?: { shopperId?: unknown }; pipeline?: unknown; consent?: unknown };
      if (source.forwardTo || (source.affinity && source.affinity.shopperId !== input.visitorId)) throw new SessionAccessError();
      if (source.consent === undefined) throw new SessionAccessError();
      sourceConsent = storedConsent(source.consent);
      ownedObjectSource = source;
    }
    sourceConsent = intersectConsent(sourceConsent, consentFromCookies(input.cookieHeader));
  }
  const shopperId = await shopperIdFor(env, tenant, input.accountId);
  if (input.principal) assertSessionTarget(input.principal, input.visitorId);
  const store = new IdentityStore(env.SESSIONS as never, tenant);

  const { outcome } = await store.link({
    visitorId: input.visitorId, shopperId, assurance: input.assurance, source: input.source,
    salted: isSalted(env), now,
  });

  const base: Omit<LinkResult, 'sessionId' | 'changes' | 'audiences' | 'cookieHeaders'> = {
    shopperId, visitorId: input.visitorId, outcome, assurance: input.assurance,
  };

  if ((env.REFLEX_HOST ?? 'session') === 'do') {
    const r = await linkOnObjectHost(env, tenant, input.visitorId, shopperId, outcome, now, sourceConsent, ownedObjectSource);
    return { ...base, cookieHeaders: [], ...r };
  }
  const r = await linkOnSessionHost(env, tenant, input.visitorId, shopperId, outcome, now, input.cookieSessionId ?? null, ownedSource, sourceConsent);
  // CW28: the browser's own record now forwards to the person and nothing else
  // points at it; the link remembers it so an erasure can reach it.
  if (r.ownSessionId) await store.noteOwnSession(input.visitorId, r.ownSessionId);
  return { ...base, sessionId: r.sessionId, changes: r.changes, audiences: r.audiences, cookieHeaders: r.cookieHeaders, consent: r.consent };
}

// ── The session host ─────────────────────────────────────────────────────────

async function linkOnSessionHost(
  env: Env, tenant: TenantId, visitorId: string, shopperId: string, outcome: LinkOutcome, now: number,
  cookieSessionId: string | null,
  ownedSource?: { id: string; data: SessionData } | null,
  consent?: Consent,
): Promise<Pick<LinkResult, 'sessionId' | 'changes' | 'audiences' | 'cookieHeaders' | 'consent'> & { ownSessionId: string | null }> {
  const sm = new SessionManager(env, { tenant });
  const none: ReflexChanges = { entered: [], exited: [], explain: [] };

  // The browser's OWN record: the one named by this visitor id, carrying no
  // identity. After a first link the `user:` key points at the person, so the
  // cookie is tried first; a record that turns out to be a person's is not the
  // browser's and is left alone.
  const own = async (sid: string | null): Promise<{ id: string; data: SessionData } | null> => {
    if (!sid) return null;
    const data = await sm.readRaw(sid);
    return data && !data.identity && data.userId === visitorId ? { id: sid, data } : null;
  };
  const browser = ownedSource !== undefined ? ownedSource : (await own(cookieSessionId)) ?? (await own(await sm.resolveSessionIdByUserId(visitorId)));
  const fromSessionId = browser?.id ?? null;
  const fromRaw = browser?.data ?? null;
  const cfg = await resolveReflexConfig(env, resolveSurface({ surface: fromRaw?.surface }));

  if (outcome === 'already') {
    // Nothing to merge; still answer with the person's session so the cookie can follow.
    const sid = await sm.resolveSessionIdByUserId(shopperId);
    const data = sid ? await sm.readRaw(sid, consent !== undefined) : null;
    if (sid && data) {
      const resolved = consent ? await sm.restrictConsent(sid, consent) : consentOf(data);
      const next = { ...data, preferences: { ...data.preferences, trackingConsent: resolved.tracking, personalizationEnabled: resolved.personalization } };
      return { sessionId: sid, changes: none, audiences: data.reflex?.audiences ?? [], cookieHeaders: sm.createCookieHeaders(sm.generateSessionCookies(next, sid)), ownSessionId: fromSessionId, consent: resolved };
    }
    // The link exists but the person's session expired: make one from what the browser has.
  }

  const absorbed = await sm.absorbIntoShopper({
    shopperId, visitorId, from: fromRaw, fromSessionId, config: cfg, now,
    mode: outcome === 'relinked' ? 'repoint' : 'merge',
    consent,
  });
  return {
    sessionId: absorbed.sessionId,
    changes: absorbed.changes,
    audiences: absorbed.data.reflex?.audiences ?? [],
    cookieHeaders: sm.createCookieHeaders(sm.generateSessionCookies(absorbed.data, absorbed.sessionId)),
    ownSessionId: fromSessionId && fromSessionId !== absorbed.sessionId ? fromSessionId : null,
    consent: consentOf(absorbed.data),
  };
}

// ── The object host ──────────────────────────────────────────────────────────

async function linkOnObjectHost(
  env: Env, tenant: TenantId, visitorId: string, shopperId: string, outcome: LinkOutcome, now: number,
  consent?: Consent, ownedSource?: { affinity?: unknown; pipeline?: unknown; forwardTo?: unknown },
): Promise<Pick<LinkResult, 'changes' | 'audiences' | 'sessionId' | 'consent'>> {
  const none: ReflexChanges = { entered: [], exited: [], explain: [] };
  const person = shopperObject(env.SHOPPER_REFLEX, shopperId, tenant);
  const browser = shopperObject(env.SHOPPER_REFLEX, visitorId, tenant);
  const personName = shopperObjectName(tenant, shopperId);
  const checked = async (response: Response) => {
    const body = await response.json() as { ok?: unknown; sessionId?: unknown; consent?: unknown; audiences?: string[]; changes?: ReflexChanges; affinity?: { audiences?: string[] } | null; pipeline?: unknown; forwardTo?: unknown };
    if (!response.ok || body?.ok !== true) throw new SessionAccessError();
    return body;
  };
  const actualSid = (value: unknown): string => {
    if (typeof value !== 'string' || !value) throw new SessionAccessError();
    return value;
  };
  const actualConsent = (value: unknown): Consent => {
    if (value === undefined) throw new SessionAccessError();
    return storedConsent(value);
  };

  if (outcome === 'already') {
    if (consent) {
      const response = await person.fetch('https://shopper-reflex/consent/refusal', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(consent) });
      consent = actualConsent((await checked(response)).consent);
    }
    const snap = await checked(await person.fetch('https://shopper-reflex/snapshot'));
    return { changes: none, audiences: snap.affinity?.audiences ?? [], sessionId: actualSid(snap.sessionId), consent };
  }

  let audiences: string[] = [];
  let changes = none;
  let sessionId: string | null = null;
  if (outcome === 'linked') {
    const exported = ownedSource ?? await checked(await browser.fetch('https://shopper-reflex/identity/export'));
    // A browser already forwarding elsewhere has nothing of its own to fold in.
    const payload = exported.forwardTo ? { shopperId, now } : { shopperId, now, affinity: exported.affinity ?? null, pipeline: exported.pipeline ?? null };
    const absorbed = await checked(await person.fetch('https://shopper-reflex/identity/absorb', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...payload, ...(consent ? { consent } : {}) }),
    }));
    if (consent) consent = actualConsent(absorbed.consent);
    sessionId = actualSid(absorbed.sessionId);
    audiences = absorbed.audiences ?? [];
    changes = absorbed.changes ?? none;
  } else {
    // relinked: make sure the person's object exists and carries the id, fold nothing.
    const absorbed = await checked(await person.fetch('https://shopper-reflex/identity/absorb', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ shopperId, now, ...(consent ? { consent } : {}) }),
    }));
    if (consent) consent = actualConsent(absorbed.consent);
    sessionId = actualSid(absorbed.sessionId);
  }
  await checked(await browser.fetch('https://shopper-reflex/identity/forward', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ to: personName }),
  }));
  return { changes, audiences, sessionId, consent };
}

// src/ledger/erasure.ts
// Doc 22 §15, CW28: erasure across the ledger. The ledger is append-only and
// its R2 partition is the warehouse's export, so "delete this visitor's rows"
// is two things with one list between them.
//
// A TOMBSTONE per visitor, written the moment erasure is requested, that every
// reader honours at once: the day report, the point lookup, the replay and the
// export listing all drop a row whose visitor is tombstoned and whose time is
// at or before the erasure. And a scheduled REWRITE that walks the tenant's
// partition newest day first over the retention window, removes those rows
// from the batch objects, deletes an object that empties, and records scan
// completion WITHOUT retiring the active suppression predicate. A run resumes where
// it stopped, and is idempotent: a day done twice removes nothing the second
// time. Aggregates are untouched, because counts are not personal data.
//
// The rows a visitor produces AFTER the erasure are new evidence, kept: an
// erasure is a point in time, not a ban. The retention window is the ledger's
// configured scan horizon, not an approved physical-retention policy. Barrier
// removal requires a later authorized lifecycle; no automatic expiry is implied.

import type { Env } from '@/types/env';

export interface Tombstone {
  tenant: string;
  visitor_id: string;
  /** When erasure was requested. Rows at or before it are hidden, then removed. */
  erased_at: number;
  actor: string;
  /** The oldest day (UTC, YYYY-MM-DD) the rewrite has already cleaned for this visitor; absent before the first pass. */
  done_through?: string;
  rows_removed: number;
  objects_rewritten: number;
  objects_deleted: number;
  /** Completed configured scan, not exhaustive/external erasure. The barrier stays active. */
  rewritten_at?: number;
  window_days?: number;
  /** Durable day coordinator; never discard this reference while recovery is pending. */
  rewrite?: { id: string; day: string };
}

/** What remains after the rewrite: the audit of an erasure, with the visitor id replaced by a hash. */
export interface RetiredTombstone {
  tenant: string;
  visitor_hash: string;
  erased_at: number;
  rewritten_at: number;
  window_days: number;
  rows_removed: number;
  objects_rewritten: number;
  objects_deleted: number;
}

export interface R2Erasable {
  put(key: string, body: string, opts?: unknown): Promise<unknown>;
  get(key: string): Promise<{ text(): Promise<string> } | null>;
  delete(key: string): Promise<unknown>;
  list(opts: { prefix: string; cursor?: string; limit?: number }): Promise<{ objects: Array<{ key: string }>; truncated: boolean; cursor?: string }>;
}
export type R2Readable = Pick<R2Erasable, 'get' | 'list'>;

export const DEFAULT_RETENTION_DAYS = 90;
const DAY = 86_400_000;

export const pendingPrefix = (tenant: string) => `erasures/${tenant}/pending/`;
export const retiredPrefix = (tenant: string) => `erasures/${tenant}/retired/`;
export const tombstoneKey = (tenant: string, visitorId: string) => `${pendingPrefix(tenant)}${encodeURIComponent(visitorId)}.json`;
const rewriteKey = (tenant: string) => `erasures/${tenant}/rewrite.json`;

export const dayOf = (ms: number): string => new Date(ms).toISOString().slice(0, 10);
const msOfDay = (day: string): number => Date.UTC(+day.slice(0, 4), +day.slice(5, 7) - 1, +day.slice(8, 10));
const prevDay = (day: string): string => dayOf(msOfDay(day) - DAY);

/** FNV-1a over the id, with its length: enough to tell audit rows apart, and no way back to the id. */
export function visitorHash(id: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < id.length; i++) { h ^= id.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return `${h.toString(16).padStart(8, '0')}-${id.length}`;
}

/** The retention window in days: `LEDGER_RETENTION_DAYS`, or the design's default. */
export function retentionDays(env: Pick<Env, 'LEDGER_RETENTION_DAYS'>): number {
  const n = Number(env.LEDGER_RETENTION_DAYS);
  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : DEFAULT_RETENTION_DAYS;
}

export async function listKeys(r2: R2Readable, prefix: string): Promise<string[]> {
  const out: string[] = [];
  let cursor: string | undefined;
  const seen = new Set<string>();
  do {
    const page = await r2.list({ prefix, cursor, limit: 1000 });
    for (const o of page.objects) out.push(o.key);
    if (page.truncated && (typeof page.cursor !== 'string' || !page.cursor || seen.has(page.cursor))) throw new Error('Erasure listing unavailable');
    cursor = page.truncated ? page.cursor : undefined;
    if (cursor) seen.add(cursor);
  } while (cursor);
  return out.sort();
}

const validSubject = (id: unknown): id is string => typeof id === 'string' && /^[A-Za-z0-9_.-]{1,200}$/.test(id);
const validTenant = (id: unknown): id is string => typeof id === 'string' && /^[a-z0-9][a-z0-9_-]{0,63}$/i.test(id);
const validTime = (n: unknown): n is number => typeof n === 'number' && Number.isSafeInteger(n) && n >= 0 && Number.isFinite(new Date(n).getTime());
const validDay = (v: unknown): v is string => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v)
  && Number.isFinite(Date.parse(v)) && dayOf(Date.parse(v)) === v;
function checkedTombstone(value: unknown, tenant: string, key: string): Tombstone {
  const t = value as Tombstone | null;
  if (!t || !validTenant(tenant) || t.tenant !== tenant || !validSubject(t.visitor_id)
    || key !== tombstoneKey(tenant, t.visitor_id) || !validTime(t.erased_at)
    || typeof t.actor !== 'string' || t.actor.length < 1 || t.actor.length > 200
    || ![t.rows_removed, t.objects_rewritten, t.objects_deleted].every(n => Number.isSafeInteger(n) && n >= 0)
    || (t.done_through !== undefined && (!validDay(t.done_through) || t.done_through > dayOf(t.erased_at)))
    || ((t.rewritten_at === undefined) !== (t.window_days === undefined))
    || (t.rewrite !== undefined && (!t.rewrite || typeof t.rewrite.id !== 'string' || !/^[a-f0-9]{32}$/.test(t.rewrite.id)
      || !validDay(t.rewrite.day) || t.rewrite.day !== (t.done_through ? prevDay(t.done_through) : dayOf(t.erased_at)) || t.rewritten_at !== undefined))
    || (t.rewritten_at !== undefined && (!validTime(t.rewritten_at) || t.rewritten_at < t.erased_at
      || !Number.isSafeInteger(t.window_days) || t.window_days! < 1
      || !Number.isFinite(new Date(t.erased_at - t.window_days! * DAY).getTime())
      || !t.done_through || t.done_through > dayOf(t.erased_at - t.window_days! * DAY)))) throw new Error('Erasure state unavailable');
  return t;
}

/** Exact active barrier, including completed scans. Only a definite missing key means no cutoff. */
export async function loadTombstone(r2: Pick<R2Readable, 'get'>, tenant: string, visitorId: string): Promise<Tombstone | null> {
  if (!r2 || typeof r2.get !== 'function' || !validTenant(tenant) || !validSubject(visitorId)) throw new Error('Erasure state unavailable');
  const key = tombstoneKey(tenant, visitorId), obj = await r2.get(key);
  if (obj === null) return null;
  if (!obj || typeof obj.text !== 'function') throw new Error('Erasure state unavailable');
  return checkedTombstone(JSON.parse(await obj.text()), tenant, key);
}

/** Every active barrier, including completed scans. Listed absence/corruption is not consent to write. */
export async function loadTombstones(r2: R2Readable, tenant: string): Promise<Map<string, Tombstone>> {
  if (!validTenant(tenant)) throw new Error('Erasure state unavailable');
  const out = new Map<string, Tombstone>();
  for (const key of await listKeys(r2, pendingPrefix(tenant))) {
    const obj = await r2.get(key);
    if (!obj) throw new Error('Erasure state unavailable');
    const t = checkedTombstone(JSON.parse(await obj.text()), tenant, key);
    out.set(t.visitor_id, t);
  }
  return out;
}

/** Is this row hidden: its visitor is tombstoned and it happened at or before the erasure. */
export function hidden(tombs: ReadonlyMap<string, Pick<Tombstone, 'erased_at'>>, rec: { visitor_id: string; ts: number }): boolean {
  const t = tombs.get(rec.visitor_id);
  return t !== undefined && rec.ts <= t.erased_at;
}

export function withoutErased<T extends { visitor_id: string; ts: number }>(records: readonly T[], tombs: ReadonlyMap<string, Pick<Tombstone, 'erased_at'>>): T[] {
  return tombs.size ? records.filter((r) => !hidden(tombs, r)) : [...records];
}

/** Same-cutoff retries preserve progress; a genuinely later erasure restarts the window. */
export async function writeTombstone(r2: R2Erasable, tenant: string, visitorId: string, actor: string, now = Date.now()): Promise<{ key: string; tombstone: Tombstone }> {
  if (!validTenant(tenant) || !validSubject(visitorId) || !validTime(now) || typeof actor !== 'string' || actor.length < 1 || actor.length > 200) throw new Error('Erasure state unavailable');
  const key = tombstoneKey(tenant, visitorId);
  let prior: Tombstone | null = null;
  const obj = await r2.get(key);
  if (obj) {
    prior = checkedTombstone(JSON.parse(await obj.text()), tenant, key);
    if (now <= prior.erased_at) return { key, tombstone: prior };
  }
  // A later cutoff must not replace the snapshots/counters of an unfinished
  // physical pass. Same/earlier requests above remain harmless barrier retries.
  const journal = await readRewrite(r2, tenant);
  if (prior?.rewrite || journal?.targets.some(t => t.base.visitor_id === visitorId)) throw new Error('Erasure rewrite recovery required');
  const tombstone: Tombstone = {
    tenant, visitor_id: visitorId, erased_at: Math.max(now, prior?.erased_at ?? 0), actor,
    rows_removed: prior?.rows_removed ?? 0, objects_rewritten: prior?.objects_rewritten ?? 0, objects_deleted: prior?.objects_deleted ?? 0,
  };
  await r2.put(key, JSON.stringify(tombstone), { httpMetadata: { contentType: 'application/json' } });
  return { key, tombstone };
}

export interface RewriteResult {
  tenant: string;
  /** Active barriers at the start, including already completed scans. */
  tombstones: number;
  /** The days this run cleaned, newest first. */
  days: string[];
  objects_opened: number;
  /** Mutations durably credited this run, including reconciled earlier attempts. */
  objects_rewritten: number;
  objects_deleted: number;
  rows_removed: number;
  /** Legacy field: scans completed this run; their active barriers are NOT retired. */
  retired: number;
  /** Physical scans still pending after the run, not the number of active barriers. */
  remaining: number;
  /** The run stopped at its object cap with days left; the next run continues. */
  more: boolean;
}

type Counts = Pick<Tombstone, 'rows_removed' | 'objects_rewritten' | 'objects_deleted'>;
interface RewriteJournal {
  version: 1;
  tenant: string;
  id: string;
  day: string;
  window_days: number;
  phase: 'preparing' | 'scanning' | 'finalizing';
  keys: string[];
  index: number;
  targets: Array<{ base: Tombstone; credit: Counts }>;
  intent?: { before: string; after: string | null; removed: number[] };
}
const zeroCounts = (): Counts => ({ rows_removed: 0, objects_rewritten: 0, objects_deleted: 0 });
const countsValid = (c: Counts): boolean => !!c && [c.rows_removed, c.objects_rewritten, c.objects_deleted].every(n => Number.isSafeInteger(n) && n >= 0);
const failRewrite = (): never => { throw new Error('Erasure rewrite state unavailable or conflicting'); };
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b);
const stateOf = (t: Tombstone): unknown[] => [t.tenant, t.visitor_id, t.erased_at, t.actor, t.done_through,
  t.rows_removed, t.objects_rewritten, t.objects_deleted, t.rewritten_at, t.window_days, t.rewrite?.id, t.rewrite?.day];
const anchored = (j: RewriteJournal, t: Tombstone): Tombstone => ({ ...t, rewrite: { id: j.id, day: j.day } });
const totalFor = (j: RewriteJournal, target: RewriteJournal['targets'][number]): Tombstone => ({
  ...target.base, done_through: j.day,
  rows_removed: target.base.rows_removed + target.credit.rows_removed,
  objects_rewritten: target.base.objects_rewritten + target.credit.objects_rewritten,
  objects_deleted: target.base.objects_deleted + target.credit.objects_deleted,
});
function checkedRewrite(value: unknown, tenant: string): RewriteJournal {
  const j = value as RewriteJournal | null;
  if (!j || j.version !== 1 || j.tenant !== tenant || typeof j.id !== 'string' || !/^[a-f0-9]{32}$/.test(j.id)
    || !validDay(j.day) || !Number.isSafeInteger(j.window_days) || j.window_days < 1
    || !['preparing', 'scanning', 'finalizing'].includes(j.phase) || !Array.isArray(j.keys)
    || !Number.isSafeInteger(j.index) || j.index < 0 || j.index > j.keys.length
    || !Array.isArray(j.targets) || !j.targets.length) return failRewrite();
  const prefix = `${tenant}/${j.day}/`;
  if (j.keys.some((key, i) => typeof key !== 'string' || !key.startsWith(prefix) || key.length <= prefix.length
    || (i > 0 && key <= j.keys[i - 1]!))) return failRewrite();
  const visitors = new Set<string>();
  for (const target of j.targets) {
    if (!target || !target.base) return failRewrite();
    const t = checkedTombstone(target.base, tenant, tombstoneKey(tenant, target.base.visitor_id));
    if (t.rewrite || t.rewritten_at !== undefined || visitors.has(t.visitor_id) || !countsValid(target.credit)
      || j.day !== (t.done_through ? prevDay(t.done_through) : dayOf(t.erased_at))
      || !Number.isFinite(new Date(t.erased_at - j.window_days * DAY).getTime())
      || j.day < dayOf(t.erased_at - j.window_days * DAY)
      || target.credit.objects_rewritten + target.credit.objects_deleted > j.index
      || target.credit.rows_removed < target.credit.objects_rewritten + target.credit.objects_deleted
      || (target.credit.rows_removed > 0 && target.credit.objects_rewritten + target.credit.objects_deleted === 0)
      || !countsValid(totalFor(j, target))) return failRewrite();
    visitors.add(t.visitor_id);
  }
  if (j.phase === 'preparing' && (j.index !== 0 || j.intent || j.targets.some(t => !same(t.credit, zeroCounts())))) return failRewrite();
  if (j.phase === 'finalizing' && (j.index !== j.keys.length || j.intent)) return failRewrite();
  if (j.intent !== undefined && (!j.intent || j.phase !== 'scanning' || j.index >= j.keys.length
    || typeof j.intent.before !== 'string' || !/^[a-f0-9]{64}$/.test(j.intent.before)
    || (j.intent.after !== null && (typeof j.intent.after !== 'string' || !/^[a-f0-9]{64}$/.test(j.intent.after)))
    || j.intent.before === j.intent.after || !Array.isArray(j.intent.removed) || j.intent.removed.length !== j.targets.length
    || !j.intent.removed.every(n => Number.isSafeInteger(n) && n >= 0) || !j.intent.removed.some(n => n > 0))) return failRewrite();
  if (j.intent) for (const [i, target] of j.targets.entries()) {
    const total = totalFor(j, target), removed = j.intent.removed[i]!;
    if (!countsValid({ rows_removed: total.rows_removed + removed,
      objects_rewritten: total.objects_rewritten + (removed > 0 && j.intent.after !== null ? 1 : 0),
      objects_deleted: total.objects_deleted + (removed > 0 && j.intent.after === null ? 1 : 0) })) return failRewrite();
  }
  return j;
}
async function readRewrite(r2: R2Readable, tenant: string): Promise<RewriteJournal | null> {
  const obj = await r2.get(rewriteKey(tenant));
  return obj ? checkedRewrite(JSON.parse(await obj.text()), tenant) : null;
}
async function putJson(r2: R2Erasable, key: string, value: unknown): Promise<void> {
  if (await r2.put(key, JSON.stringify(value), { httpMetadata: { contentType: 'application/json' } }) === null) failRewrite();
}
async function saveRewrite(r2: R2Erasable, j: RewriteJournal): Promise<void> {
  checkedRewrite(j, j.tenant);
  await putJson(r2, rewriteKey(j.tenant), j);
}
async function currentTarget(r2: R2Readable, tenant: string, visitor: string): Promise<Tombstone> {
  const key = tombstoneKey(tenant, visitor), obj = await r2.get(key);
  if (!obj) return failRewrite();
  return checkedTombstone(JSON.parse(await obj.text()), tenant, key);
}
async function fingerprint(body: string): Promise<string> {
  const hash = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(body));
  return [...new Uint8Array(hash)].map(b => b.toString(16).padStart(2, '0')).join('');
}
function filterObject(body: string, j: RewriteJournal): { body: string | null; removed: number[] } {
  const kept: string[] = [], removed = j.targets.map(() => 0);
  const targets = new Map(j.targets.map((t, index) => [t.base.visitor_id, { at: t.base.erased_at, index }]));
  for (const line of body.split('\n')) {
    if (!line) continue;
    let rec: { visitor_id?: unknown; ts?: unknown } | null = null;
    try { rec = JSON.parse(line); } catch { kept.push(line); continue; }
    const target = typeof rec?.visitor_id === 'string' ? targets.get(rec.visitor_id) : undefined;
    if (target && typeof rec?.ts === 'number' && rec.ts <= target.at) removed[target.index]!++;
    else kept.push(line);
  }
  return { body: kept.length ? kept.join('\n') + '\n' : null, removed };
}

/**
 * One shared, manifest-bound pass per day. The object budget includes recovery
 * reads, not metadata/listing operations. The manifest still has whole-day
 * listing/memory cost; this is not a physical-deletion SLA or a concurrent-writer
 * fence. Incompatible rollback must preserve the journal and its anchors.
 */
export async function rewriteErasures(r2: R2Erasable, tenant: string, opts: { now?: number; retentionDays?: number; maxObjects?: number } = {}): Promise<RewriteResult> {
  const now = opts.now ?? Date.now(), window = opts.retentionDays ?? DEFAULT_RETENTION_DAYS, cap = opts.maxObjects ?? 5000;
  if (!validTime(now) || !Number.isSafeInteger(window) || window < 1 || !Number.isSafeInteger(cap) || cap < 1
    || !Number.isFinite(new Date(now - window * DAY).getTime())) throw new Error('Erasure scan unavailable');
  const today = dayOf(now), tombs = await loadTombstones(r2, tenant);
  let journal = await readRewrite(r2, tenant);
  for (const t of tombs.values()) if (t.rewrite && (!journal || t.rewrite.id !== journal.id || t.rewrite.day !== journal.day
    || !journal.targets.some(target => target.base.visitor_id === t.visitor_id))) failRewrite();
  const result: RewriteResult = { tenant, tombstones: tombs.size, days: [], objects_opened: 0, objects_rewritten: 0,
    objects_deleted: 0, rows_removed: 0, retired: 0, remaining: [...tombs.values()].filter(t => t.rewritten_at === undefined).length, more: false };
  const floorOf = (t: Tombstone) => dayOf(t.erased_at - window * DAY);
  const nextOf = (t: Tombstone) => t.done_through ? prevDay(t.done_through) : dayOf(t.erased_at);
  while (true) {
    if (!journal) {
      const eligible = [...tombs.values()].filter(t => t.rewritten_at === undefined && nextOf(t) >= floorOf(t) && nextOf(t) < today);
      if (!eligible.length) break;
      if (result.objects_opened >= cap) { result.more = true; break; }
      const day = eligible.map(nextOf).sort().reverse()[0]!;
      journal = { version: 1, tenant, id: crypto.randomUUID().replace(/-/g, ''), day, window_days: window, phase: 'preparing',
        keys: await listKeys(r2, `${tenant}/${day}/`), index: 0,
        targets: eligible.filter(t => nextOf(t) === day).map(base => ({ base, credit: zeroCounts() })) };
      await saveRewrite(r2, journal); // Even ambiguous creation precedes every anchor/mutation.
    }
    let j: RewriteJournal = journal;
    if (j.window_days !== window || j.day >= today) failRewrite();
    // Complete partial anchor installation before touching any ledger object.
    for (const target of j.targets) {
      const current = await currentTarget(r2, tenant, target.base.visitor_id), expected = anchored(j, target.base);
      if (j.phase === 'finalizing' && same(stateOf(current), stateOf(totalFor(j, target)))) continue;
      if (!same(stateOf(current), stateOf(expected))) {
        if (j.phase !== 'preparing' || !same(stateOf(current), stateOf(target.base))) failRewrite();
        await putJson(r2, tombstoneKey(tenant, current.visitor_id), expected);
      }
      tombs.set(current.visitor_id, expected);
    }
    if (j.phase === 'preparing') {
      j = { ...j, phase: 'scanning' };
      await saveRewrite(r2, j);
    }
    while (j.phase === 'scanning' && j.index < j.keys.length && result.objects_opened < cap) {
      const key = j.keys[j.index]!;
      result.objects_opened++;
      const obj = await r2.get(key), body = obj ? await obj.text() : null;
      const before = body === null ? null : await fingerprint(body);
      if (!j.intent) {
        const filtered = body === null ? null : filterObject(body, j);
        if (!filtered || !filtered.removed.some(n => n > 0)) {
          const next = { ...j, index: j.index + 1 };
          await saveRewrite(r2, next); // A listed missing object earns zero removal credit.
          j = next;
          continue;
        }
        j = { ...j, intent: { before: before!, after: filtered.body === null ? null : await fingerprint(filtered.body), removed: filtered.removed } };
        await saveRewrite(r2, j); // No destructive call without a durable exact intent.
      }
      const intent = j.intent!;
      if (before === intent.before && body !== null) {
        const filtered = filterObject(body, j);
        if (!same(filtered.removed, intent.removed) || (filtered.body === null ? null : await fingerprint(filtered.body)) !== intent.after) failRewrite();
        if (filtered.body === null) await r2.delete(key);
        else if (await r2.put(key, filtered.body) === null) failRewrite();
      } else if (before !== intent.after) failRewrite();
      // Exact after-state includes absence only for an intended committed delete.
      const targets = j.targets.map((target, i) => ({
        ...target,
        credit: {
          rows_removed: target.credit.rows_removed + intent.removed[i]!,
          objects_rewritten: target.credit.objects_rewritten + (intent.removed[i]! > 0 && intent.after !== null ? 1 : 0),
          objects_deleted: target.credit.objects_deleted + (intent.removed[i]! > 0 && intent.after === null ? 1 : 0),
        },
      }));
      const next: RewriteJournal = { ...j, targets, index: j.index + 1 };
      delete next.intent;
      await saveRewrite(r2, next); // Cursor and every visitor's credit are one checkpoint.
      result.rows_removed += intent.removed.reduce((a, b) => a + b, 0);
      if (intent.after === null) result.objects_deleted++; else result.objects_rewritten++;
      j = next;
    }
    if (j.index < j.keys.length) { journal = j; result.more = true; break; }
    if (j.phase !== 'finalizing') {
      j = { ...j, phase: 'finalizing' };
      await saveRewrite(r2, j);
    }
    for (const target of j.targets) {
      const current = await currentTarget(r2, tenant, target.base.visitor_id), final = totalFor(j, target);
      if (!same(stateOf(current), stateOf(final))) {
        if (!same(stateOf(current), stateOf(anchored(j, target.base)))) failRewrite();
        await putJson(r2, tombstoneKey(tenant, current.visitor_id), final);
      }
      tombs.set(current.visitor_id, final);
    }
    // Failure before/after this deletion is safe: all absolute target snapshots
    // have already been acknowledged, and a retained journal accepts them again.
    await r2.delete(rewriteKey(tenant));
    result.days.push(j.day);
    journal = null;
  }
  for (const t of tombs.values()) {
    if (t.rewritten_at === undefined && !t.rewrite && t.done_through && t.done_through <= floorOf(t)) {
      const retired: RetiredTombstone = {
        tenant, visitor_hash: visitorHash(t.visitor_id), erased_at: t.erased_at, rewritten_at: now, window_days: window,
        rows_removed: t.rows_removed, objects_rewritten: t.objects_rewritten, objects_deleted: t.objects_deleted,
      };
      await putJson(r2, `${retiredPrefix(tenant)}${t.erased_at.toString(36)}-${retired.visitor_hash}.json`, retired);
      const completed = { ...t, rewritten_at: now, window_days: window };
      await putJson(r2, tombstoneKey(tenant, t.visitor_id), completed);
      tombs.set(t.visitor_id, completed);
      result.retired++;
    }
  }
  result.remaining = [...tombs.values()].filter(t => t.rewritten_at === undefined).length;
  return result;
}

/**
 * The ledger half of an erasure, in one call for the identity route to make:
 * the tombstone, so every reader hides the rows now and the rewrite removes
 * them; and the visitor's own ring of served decisions, emptied. The profile
 * and the long index live in the shopper's object, which the identity route
 * erases itself.
 */
export async function resetVisitorRing(env: Pick<Env, 'DECISION_RING'>, tenant: string, visitorId: string): Promise<'reset' | 'unbound' | 'failed'> {
  let ring: 'reset' | 'unbound' | 'failed' = 'unbound';
  const ns = env.DECISION_RING;
  if (ns) {
    try {
      const res = await ns.get(ns.idFromName(`${tenant}:${visitorId}`)).fetch('https://learn/reset', { method: 'POST' });
      const body = await res.json() as { ok?: unknown; reset?: unknown };
      ring = res.ok && body.ok === true && body.reset === true ? 'reset' : 'failed';
    } catch { ring = 'failed'; }
  }
  return ring;
}

export async function eraseVisitorLedger(env: Pick<Env, 'STORAGE' | 'DECISION_RING'>, tenant: string, visitorId: string, actor: string, now = Date.now()): Promise<{ ok: boolean; tombstone: { key: string; erased_at: number }; ring: 'reset' | 'unbound' | 'failed' }> {
  const { key, tombstone } = await writeTombstone(env.STORAGE as unknown as R2Erasable, tenant, visitorId, actor, now);
  const ring = await resetVisitorRing(env, tenant, visitorId);
  return { ok: ring !== 'failed', tombstone: { key, erased_at: tombstone.erased_at }, ring };
}

// src/reflex/core.ts
// ─────────────────────────────────────────────────────────────────────────────
// ReflexCore — the pure heart of the Edge Affinity Reflex (doc 16 §4, §12).
//
// A deterministic, recency/frequency-weighted, time-DECAYED affinity engine:
// per catalog dimension (line, silhouette, occasion, …) it keeps a raw score
// per value and derives a normalized affinity a ∈ [0,1]. Shoppers ENTER an
// affinity audience when a crosses θ_in and EXIT when it decays below θ_out —
// the Dynamic-Yield-style "move in and out by behavior", made glass.
//
// Invariants (doc 16 §4 — what makes this an engine, not a demo trick):
//   • Store raw, read lazily. State is only (R, tLast) — NEVER pre-decayed.
//     Every read computes R_eff = R · exp(−Δt/τ) as a pure function of time.
//     Nothing mutates on a timer; replays are deterministic.
//   • The engine clock is authoritative — the HOST stamps `now` (client ts is
//     advisory); apply() never reads Date.now() itself.
//   • apply(state, input, now, config) → (state′, changes) is a PURE function:
//     no I/O, no ambient state. It is the testing seam and the portability
//     seam (request path today → ShopperReflex DO in P2, unchanged).
//
// NO ML. Where real ML belongs (propensity/churn) it lives in ODP predictive
// insights; discovery/suggestion belongs to Opal. This module is math.
// ─────────────────────────────────────────────────────────────────────────────

/** One catalog axis affinity is computed on. Catalog-agnostic by construction (D-6). */
export interface DimensionSpec {
  /** Dimension key, e.g. 'line' | 'silhouette' | 'occasion' | 'priceBand'. */
  key: string;
  /** Product field the value(s) come from, e.g. 'line' or 'price_usd'. */
  source: string;
  /** The field is an array (e.g. occasion[]) — each entry is touched. */
  multi?: boolean;
  /** Derived dimension: bucket a numeric source into labeled bands. */
  derive?: 'band';
  /** Band cut points (ascending), e.g. [150, 400]. */
  cuts?: number[];
  /** Band labels, length = cuts.length + 1, e.g. ['entry','core','elevated']. */
  labels?: string[];
  /** Per-dimension overrides of the global tuning (τ/K/θ). */
  tauMs?: number;
  K?: number;
  thetaIn?: number;
  thetaOut?: number;
}

/** Versioned engine tuning. Lives in config/KV — tuning is never a redeploy. */
export interface ReflexConfig {
  version: string;
  dimensions: DimensionSpec[];
  /** Action → accumulation weight. Unknown actions weigh 0 (still re-evaluate). */
  weights: Record<string, number>;
  /** Global decay half-life-ish time constant τ (ms): R_eff = R·exp(−Δt/τ). */
  tauMs: number;
  /** Saturation midpoint: a = R/(R+K) → a=0.5 at R=K. */
  K: number;
  /** Enter threshold (a ≥ θ_in enters). */
  thetaIn: number;
  /** Exit threshold (a < θ_out exits). θ_out < θ_in = hysteresis, no flapping. */
  thetaOut: number;
  /** Prune floor: entries whose R_eff falls below this are dropped. */
  epsilon: number;
  /** Safety cap on distinct values tracked per dimension (evict weakest). */
  maxValuesPerDim: number;
  /**
   * Where a product event's touches come from when the product is not in a
   * catalog this engine holds. `catalog-only` (the default, and the demo
   * surfaces' posture) drops it. `event-when-unknown` scores the attributes the
   * event itself carries, bounded to the registry's dimensions, which is what a
   * customer's site needs: their events, their catalog, not a copy of it here.
   */
  eventAttributes?: 'catalog-only' | 'event-when-unknown';
}

/** Raw per-value accumulator — s is NEVER pre-decayed; t is the last touch. */
export interface ReflexEntry {
  s: number;
  t: number;
}

/** JSON-safe per-shopper state. Rides the session in P0; ctx.storage in P2. */
export interface ReflexState {
  v: 1;
  /** dims[dimensionKey][originalValue] → (raw score, last-touch ms). */
  dims: Record<string, Record<string, ReflexEntry>>;
  /** Current audience memberships (audience keys), sorted for determinism. */
  audiences: string[];
  /** ReflexConfig.version this state was last evaluated under. */
  configVersion: string;
}

/** A single (dimension, value) hit extracted from a product interaction. */
export interface Touch {
  dim: string;
  value: string;
}

/** What the host feeds apply(): a normalized action + its catalog touches. */
export interface ReflexInput {
  action: string;
  touches: Touch[];
}

/** Why a membership changed — the glass-box record (doc 16 §12). */
export interface ExplainRecord {
  ts: number;
  audience: string;
  dim: string;
  value: string;
  direction: 'enter' | 'exit';
  /** Affinity a at the moment of the transition (0 if pruned to nothing). */
  score: number;
  thetaIn: number;
  thetaOut: number;
  /** The action that triggered evaluation ('tick' = time-only re-eval). */
  trigger: string;
  configVersion: string;
}

export interface ReflexChanges {
  entered: string[];
  exited: string[];
  explain: ExplainRecord[];
}

export interface ReflexResult {
  state: ReflexState;
  changes: ReflexChanges;
}

/** Live affinity snapshot for the client instrument (original value names). */
export interface AffinitySnapshot {
  dims: Record<string, Record<string, number>>;
  audiences: string[];
}

// ── Naming (single source of truth — the P1 generator imports these) ─────────

/** Lowercase slug: non-alphanumerics collapse to '_'. 'Date-Night' → 'date_night'. */
export function slugValue(v: string): string {
  return v
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

/** Dimension-namespaced audience key: 'line' + 'Tabby' → 'line_tabby_affinity'. */
export function audienceKey(dim: string, value: string): string {
  return `${slugValue(dim)}_${slugValue(value)}_affinity`;
}

/** Flattened attribute key for evaluateCondition: 'line_affinity.tabby'. */
export function affinityAttrKey(dim: string, value: string): string {
  return `${slugValue(dim)}_affinity.${slugValue(value)}`;
}

